// === Tab: Emoji ===
class Emoji {
	constructor(rank, sym, cat, subcat, name, catrank, grank, catsize, pos, ang) {
		this.symbol = sym;
		this.cat = cat.toLowerCase();
		this.subcat = subcat.toLowerCase();
		this.name = name.toLowerCase();
		this.rank = rank;
		this.catrank = catrank;
		this.grank = grank;
		this.catsize = catsize;
		this.pos = pos;
		this.ang = atan2(pos.y / 12, pos.x);
		this.s = height / 30;
		this.ts = height / 30;
		this.stretch = 0;
		this.maxstretch = max(height / 20, ((height / 3) - abs(pos.x)) + height / 20);
		if (this.pos.x==0) this.maxstretch = (height / 3) - abs(pos.y) + height / 30;
	}
	show() {
		this.s = lerp(this.s, this.ts, 0.1);
		push();
		translate(this.pos);
		noStroke();
		if (this != selected) {
			textSize(this.ts / 2.5)
			if (rank == 'category') text(this.catrank, 0, this.s / 1.5);
			if (rank == 'overall') text(this.rank, 0, this.s / 1.5);
		}
		if (this == selected) {
			fill(255);
			rectMode(CENTER);
			rect(0, 0, this.ts, this.ts)
			fill(0)
			this.ts = height / 16;
			if (this.stretch < this.maxstretch) this.stretch += height / 60;
			rotate(this.ang);
			translate(this.s / 2, 0);
			stroke(0, 50);
			strokeWeight(height / 300);
			line(0, 0, 0.95 * this.stretch, 0);
			translate(this.stretch, 0);
			noStroke();
			rotate(-this.ang);
			if (abs(this.pos.x) < 1 && this.pos.y >= 0) textAlign(CENTER, TOP);
			else if (abs(this.pos.x) < 1 && this.pos.y < 0) textAlign(CENTER, BOTTOM);
			else if (this.pos.x > 0) textAlign(LEFT, CENTER);
			else if (this.pos.x < 0) textAlign(RIGHT, CENTER);
			textSize(this.s);
			if (this == selected) {
				if (this.pos.x > 0) text(this.symbol + this.name, 0, 0);
				else text(this.name + this.symbol, 0, 0);
			}
		} else {
			this.ts = height / 30;
			this.stretch = 0;
		}
		pop();
	}
	contains(x, y) {
		return (dist(x, y, this.pos.x, this.pos.y) < this.s);
	}
}

