// For the #WCCChallenge, theme: "zoo".
// Here are the 120 unicode emojis in the "animal and nature" category!
// There are 15 birds, 12 bugs, 53 mammals, 9 marine animals, 8 reptiles, 10 flowers, 12 plants, and 1 amphibian.
// Data on emoji meanings and usage frequency from the Unicode Foundation:
// https://home.unicode.org/emoji/emoji-frequency/

let emojis = [];
let categories = [];
let catsizes = [];
let positions = [];
let selected;
let pick = null;
let zoom;
let rank = 'category';
let sort = 'Random';
let sorts = ['Random', 'Category', 'Rank'];
let sortindex = 0;
let zoo;

function preload() {
	table1 = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/zooanimals3.csv', 'header');
	table2 = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/zooanimals2.csv', 'header');
