function setup() {
	createCanvas(windowWidth, windowHeight);
	zoo = createGraphics(width, height);
	zoom = 1;
	textAlign(CENTER, CENTER);
	makePositions();
	makeEmojis();
	button = createButton('Category Rank');
	button.style('font-size', '18px');
	button.position(10, 10);
