	button2.style('width','150px');
	announce = createP('Test');
	announce.position(10, 30)
	announce.style('font-size', '18px');
	announce.style('font-family', 'Arial')
}

function draw() {
	background(255);
	image(zoo, 0, 0)
	translate(width / 2, height / 2);
	scale(zoom);
	for (let e of emojis) {
		if (e == selected) continue;
		e.show();
	}
	if (selected) {
		selected.show();
		let txt = 'name: ' + selected.name + '</br>'
		txt += 'category: ' + selected.cat + '</br>'
		txt += 'subcategory: ' + selected.subcat + '</br>'
		if (rank == 'category') txt += 'category rank: ' + selected.catrank + '</br>'
		else if (rank == 'overall') txt += 'overall rank: ' + selected.rank + '</br>'
		announce.html(txt)
	} else {
		let txt = 'name: ' + '</br>'
		txt += 'category: ' + '</br>'
		txt += 'subcategory: ' + '</br>'
		if (rank == 'category') txt += 'category rank: ' + '</br>'
		else if (rank == 'overall') txt += 'overall rank: ' + '</br>'
		announce.html(txt)
	}
	drawCage();
}

function mouseMoved() {
	selected = null;
	for (let e of emojis) {
		if (e.contains(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / zoom, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / zoom)) {
			selected = e;
			break;
		}
	}
}

function makeEmojis() {
	if (sort == 'Random') table = table1;
	else if (sort == 'Category') table = table1;
	else table = table2;
	emojis = [];
	let ang = -HALF_PI;
	zoo.clear();
	makePositions();
	for (let i = 0; i < table.getRowCount(); i++) {
		let rank = table.getString(i, 1);
		let sym = table.getString(i, 2);
		let cat = table.getString(i, 4);
		let subcat = table.getString(i, 5);
		let name = table.getString(i, 6);
		let catrank = table.getString(i, 7);
		let grank = table.getString(i, 8);
		let catsize = catsizes[categories.indexOf(subcat)];
		let pos;
		if (sort == 'Random') pos = random(positions);
		else pos = positions[i];
		emojis.push(new Emoji(rank, sym, cat, subcat, name, catrank, grank, catsize, pos, ang));
		if (sort == 'Random') positions.splice(positions.indexOf(pos), 1);
	}

	for (let e of emojis) {
		zoo.push();
		zoo.translate(width / 2, height / 2);
		zoo.translate(e.pos);
		zoo.textSize(height / 30);
		zoo.textAlign(CENTER, CENTER)
		zoo.text(e.symbol, 0, 0);
		zoo.pop();
	}
	zoo.push();
	zoo.translate(width / 2, height / 2);
	zoo.textAlign(CENTER, CENTER);
	zoo.textSize(height / 20);
	zoo.text("☮️", 0, height / 150);
	zoo.pop();
	frameCount = 0;
}

function changeRank() {
	if (rank == 'category') {
		rank = 'overall';
		button.html('Overall Rank');
	} else {
		rank = 'category';
		button.html('Category Rank');
	}
}

function changeSort() {
	sortindex = (sortindex + 1) % 3;
	button2.html(sorts[(sortindex+1)%3] + ' Sort');
	sort = sorts[sortindex];
	makePositions();
	makeEmojis();
}

function makePositions() {
	positions = [];
	let num = 11;
	for (let row = 0; row < num; row++) {
		for (let col = 0; col < num; col++) {
			let x = map(col, 0, num - 1, -height / 3, height / 3);
			let y = map(row, 0, num - 1, -height / 3, height / 3);
			if (x == 0 && y == 0) continue;
			let pos = createVector(x, y);
			positions.push(pos);
		}
	}
}

function drawCage() {
	push();
	rectMode(CENTER);
	noFill();
	stroke(100, 50);
	strokeWeight(height / 300);
	strokeCap(SQUARE);
	for (let i = 0; i < 12; i++) {
		let x = map(i, 0, 11, -height / 2.7, height / 2.7);
		line(x, -height / 2.7, x, height / 2.7);
		line(-height / 2.7, x, height / 2.7, x)
	}
	pop();
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
